// Shows a placeholder hint (e.g. "PI-2K26-XXX") in the Invoice No. field when
// "Proforma Invoice" is selected, WITHOUT filling in an actual value — the real
// number is auto-generated by Invoice.save() when the field is left blank.
// Filling in a real value here would stop that auto-generation from running.
(function() {
    function init() {
        var $ = django.jQuery;
        var $type = $('#id_document_type');
        var $no = $('#id_invoice_no');
        if (!$type.length || !$no.length) return;

        function updatePlaceholder() {
            if ($type.val() === 'proforma') {
                var yr = new Date().getFullYear().toString().slice(-2);
                $no.attr('placeholder', 'PI-2K' + yr + '-XXX (auto-generated if left blank)');
            } else {
                $no.attr('placeholder', '');
            }
        }

        $type.on('change', updatePlaceholder);
        updatePlaceholder();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();